const res = await fetch('/debug/dist/app.min.js.map');
const map = await res.json();
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function decodeVLQ(str) {
  let results = [];
  let shift = 0, value = 0;
  for (let i = 0; i < str.length; i++) {
    let digit = B64.indexOf(str[i]);
    let cont = digit & 32;
    digit &= 31;
    value += digit << shift;
    if (cont) { shift += 5; }
    else {
      let neg = value & 1;
      value >>>= 1;
      results.push(neg ? -value : value);
      value = shift = 0;
    }
  }
  return results;
}
const lines = map.mappings.split(';');
let genLine = 0;
let out = [];
let srcFile=0, srcLine=0, srcCol=0;
for (const line of lines) {
  let genCol = 0;
  if (line.length) {
    for (const seg of line.split(',')) {
      const d = decodeVLQ(seg);
      genCol += d[0];
      if (d.length > 1) {
        srcFile += d[1]; srcLine += d[2]; srcCol += d[3];
      }
      out.push({genLine, genCol, srcFile, srcLine, srcCol});
    }
  }
  genLine++;
}
// find segment covering genLine=0(row1), genCol=231
const candidates = out.filter(o=>o.genLine===0 && o.genCol<=231).sort((a,b)=>b.genCol-a.genCol);
({top: candidates.slice(0,3), sourceName: map.sources[0]});

