function findByText(root, text) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
  let node;
  while (node = walker.nextNode()) {
    if (node.tagName === 'BUTTON' && node.textContent.trim() === text) return node;
  }
  return null;
}
const btn = findByText(document.body, 'Pay now');
const results = [];
for (const sheet of document.styleSheets) {
  let rules;
  try { rules = sheet.cssRules; } catch(e) { continue; }
  for (const rule of rules) {
    if (rule.selectorText && btn.matches(rule.selectorText)) {
      results.push({selector: rule.selectorText, cssText: rule.style.cssText, href: sheet.href});
    }
  }
}
JSON.stringify(results, null, 2);

